// Design-token generator (DS-001, D-034).
//
// tokens.json and brand.json are the single source of truth. This module turns
// them into the web Tailwind theme and the Flutter token classes, and checks
// the rules that keep both apps consistent (valid values, WCAG AA contrast,
// the font family declared where it is loaded). No dependencies on purpose.

import { readFileSync } from 'node:fs';
import { join } from 'node:path';

export const GENERATED_NOTE =
  'GENERATED by packages/design_tokens/generate.mjs. Do not edit by hand.';

/** WCAG AA minimum contrast for normal-size text. */
export const WCAG_AA_NORMAL_TEXT = 4.5;

/** Output files, relative to the repository root. */
export const OUTPUT_PATHS = {
  css: 'apps/admin_web/src/app/tokens.css',
  brandTs: 'apps/admin_web/src/lib/brand.ts',
  dartColors: 'packages/flutter_shared/lib/src/tokens/app_colors.dart',
  dartTypography: 'packages/flutter_shared/lib/src/tokens/app_typography.dart',
  dartRadius: 'packages/flutter_shared/lib/src/tokens/app_radius.dart',
  dartSpacing: 'packages/flutter_shared/lib/src/tokens/app_spacing.dart',
  dartLayout: 'packages/flutter_shared/lib/src/tokens/app_layout.dart',
  dartComponents:
    'packages/flutter_shared/lib/src/tokens/app_component_tokens.dart',
  dartPalette: 'packages/flutter_shared/lib/src/tokens/app_palette.dart',
  dartBrand: 'packages/flutter_shared/lib/src/brand/app_brand.dart',
};

/** Files that must agree with the font token. */
export const FONT_CONSUMERS = {
  flutterPubspec: 'packages/flutter_shared/pubspec.yaml',
  webFonts: 'apps/admin_web/src/app/fonts.ts',
};

const HEX = /^#[0-9A-Fa-f]{6}$/;
const WEIGHTS = new Set([100, 200, 300, 400, 500, 600, 700, 800, 900]);
const IDENTIFIER = /^[a-z][A-Za-z0-9]*$/;
const TOKEN_NAME = /^[a-z][A-Za-z0-9]*(\.[a-z][A-Za-z0-9]*)*$/;

export function readJson(root, file) {
  return JSON.parse(readFileSync(join(root, file), 'utf8'));
}

/** `brand.primaryStrong` → `brandPrimaryStrong`. */
export function camelName(token) {
  return token
    .split('.')
    .map((part, index) =>
      index === 0 ? part : part[0].toUpperCase() + part.slice(1),
    )
    .join('');
}

/** `brand.primaryStrong` → `brand-primary-strong`. */
export function kebabName(token) {
  return token
    .split('.')
    .map((part) => part.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`))
    .join('-');
}

/** px → rem string without trailing zeros (16 px root). */
export function rem(px) {
  return `${Number((px / 16).toFixed(4))}rem`;
}

function channel(value) {
  const c = value / 255;
  return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
}

/** WCAG 2.x relative luminance of `#RRGGBB`. */
export function luminance(hex) {
  const n = Number.parseInt(hex.slice(1), 16);
  const r = channel((n >> 16) & 0xff);
  const g = channel((n >> 8) & 0xff);
  const b = channel(n & 0xff);
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

/** WCAG 2.x contrast ratio between two opaque colours. */
export function contrastRatio(a, b) {
  const la = luminance(a);
  const lb = luminance(b);
  return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05);
}

/**
 * Component properties (D-039) name a base token: `radius` a radius token,
 * `minHeight` a layout token and every other property a colour token.
 */
export const COMPONENT_PROPERTY_GROUPS = {
  radius: 'radius',
  minHeight: 'layout',
};

export function componentPropertyGroup(property) {
  return COMPONENT_PROPERTY_GROUPS[property] ?? 'color';
}

/** A component's properties without `use`, as `[property, tokenName]`. */
export function componentProperties(component) {
  return Object.entries(component).filter(([property]) => property !== 'use');
}

function positiveNumber(value) {
  return typeof value === 'number' && Number.isFinite(value) && value > 0;
}

function entries(group) {
  return Object.entries(group ?? {}).filter(([key]) => !key.startsWith('$'));
}

/** The name of the base look (web portal and Shop App). */
export const STANDARD_THEME = 'standard';

/** `standard` followed by every theme in tokens.json `themes`. */
export function themeNames(tokens) {
  return [STANDARD_THEME, ...entries(tokens.themes).map(([name]) => name)];
}

/**
 * The tokens as one theme sees them: the base tokens with that theme's colour
 * values, font family and component references applied (D-057).
 */
export function resolveTheme(tokens, name) {
  if (name === STANDARD_THEME) return tokens;
  const theme = tokens.themes?.[name];
  if (theme === undefined) throw new Error(`unknown theme "${name}"`);
  const resolved = structuredClone(tokens);
  for (const [token, value] of entries(theme.color)) {
    if (resolved.color[token] !== undefined) {
      resolved.color[token] = { ...resolved.color[token], value };
    }
  }
  resolved.font = { ...resolved.font, ...theme.font };
  for (const [component, properties] of entries(theme.component)) {
    if (resolved.component[component] === undefined) continue;
    resolved.component[component] = {
      ...resolved.component[component],
      ...properties,
    };
  }
  return resolved;
}

/**
 * Returns a list of problems; an empty list means the tokens are valid.
 * `files` maps FONT_CONSUMERS keys to their text (omit to skip those checks).
 */
export function validate(tokens, brand, files = {}) {
  const problems = [];

  for (const [name, token] of entries(tokens.color)) {
    if (!TOKEN_NAME.test(name)) problems.push(`color "${name}": invalid name`);
    if (!HEX.test(token.value ?? '')) {
      problems.push(`color "${name}": value must be #RRGGBB`);
    }
  }

  problems.push(...validateContrast(tokens));

  for (const [name, style] of entries(tokens.typography)) {
    if (!IDENTIFIER.test(name)) {
      problems.push(`typography "${name}": invalid name`);
    }
    if (!positiveNumber(style.size)) {
      problems.push(`typography "${name}": size must be a positive number`);
    }
    if (!WEIGHTS.has(style.weight)) {
      problems.push(`typography "${name}": weight must be 100–900 in 100s`);
    }
  }

  for (const group of ['radius', 'layout', 'container']) {
    for (const [name, token] of entries(tokens[group])) {
      if (!IDENTIFIER.test(name))
        problems.push(`${group} "${name}": invalid name`);
      if (!positiveNumber(token.value)) {
        problems.push(`${group} "${name}": value must be a positive number`);
      }
    }
  }

  problems.push(...validateComponents(tokens));
  problems.push(...validateThemes(tokens));

  for (const [name, value] of entries(tokens.breakpoint)) {
    if (!IDENTIFIER.test(name) || !positiveNumber(value)) {
      problems.push(`breakpoint "${name}": invalid`);
    }
  }

  const scale = tokens.spacing.scale;
  if (
    !scale.every(
      (step) => positiveNumber(step) && step % tokens.spacing.base === 0,
    )
  ) {
    problems.push(
      `spacing: every step must be a multiple of ${tokens.spacing.base}`,
    );
  }

  const { family, webVariable } = tokens.font;
  if (typeof family !== 'string' || family.trim() === '') {
    problems.push('font.family is required');
  }
  if (!/^--[a-z][a-z0-9-]*$/.test(webVariable ?? '')) {
    problems.push('font.webVariable must be a CSS custom property name');
  }
  if (files.flutterPubspec !== undefined) {
    const families = new Set(
      themeNames(tokens).map((name) => resolveTheme(tokens, name).font.family),
    );
    for (const themeFamily of families) {
      if (typeof themeFamily !== 'string') continue;
      const declared = new RegExp(
        `^\\s*- family: ${escapeRegExp(themeFamily)}\\s*$`,
        'm',
      );
      if (!declared.test(files.flutterPubspec)) {
        problems.push(
          `font "${themeFamily}" is not declared in ${FONT_CONSUMERS.flutterPubspec} (add its font files there)`,
        );
      }
    }
  }
  if (
    files.webFonts !== undefined &&
    !files.webFonts.includes(`'${webVariable}'`)
  ) {
    problems.push(
      `${FONT_CONSUMERS.webFonts} must load the font with variable '${webVariable}'`,
    );
  }

  for (const [key, value] of entries(brand)) {
    if (typeof value !== 'string' || value.trim() === '') {
      problems.push(`brand "${key}" must be a non-empty string`);
    }
  }

  return problems;
}

/** Every readable text pair must meet WCAG AA. */
function validateContrast(tokens) {
  const problems = [];
  for (const [fg, bg] of tokens.contrastPairs.pairs) {
    const a = tokens.color[fg]?.value;
    const b = tokens.color[bg]?.value;
    if (!a || !b) {
      problems.push(`contrast pair ${fg} on ${bg}: unknown colour token`);
      continue;
    }
    if (!HEX.test(a) || !HEX.test(b)) continue;
    const ratio = contrastRatio(a, b);
    if (ratio < WCAG_AA_NORMAL_TEXT) {
      problems.push(
        `contrast pair ${fg} on ${bg}: ${ratio.toFixed(2)}:1 is below WCAG AA (${WCAG_AA_NORMAL_TEXT}:1)`,
      );
    }
  }
  return problems;
}

/**
 * A theme may only override existing tokens and component properties, and
 * the resolved theme must pass the same contrast and component checks.
 */
function validateThemes(tokens) {
  const problems = [];
  for (const [name, theme] of entries(tokens.themes)) {
    const at = `theme "${name}"`;
    const before = problems.length;
    if (!IDENTIFIER.test(name) || name === STANDARD_THEME) {
      problems.push(`${at}: invalid name`);
      continue;
    }
    if (typeof theme.use !== 'string' || theme.use.trim() === '') {
      problems.push(`${at}: "use" is required`);
    }
    for (const [token, value] of entries(theme.color)) {
      if (tokens.color[token] === undefined) {
        problems.push(`${at} color "${token}": not a base colour token`);
      } else if (!HEX.test(value ?? '')) {
        problems.push(`${at} color "${token}": value must be #RRGGBB`);
      }
    }
    if (theme.font !== undefined) {
      const keys = Object.keys(theme.font);
      if (
        keys.some((key) => key !== 'family') ||
        typeof theme.font.family !== 'string' ||
        theme.font.family.trim() === ''
      ) {
        problems.push(`${at}: font may only set a non-empty "family"`);
      }
    }
    for (const [component, properties] of entries(theme.component)) {
      const base = tokens.component?.[component];
      if (base === undefined) {
        problems.push(`${at} component "${component}": not a base component`);
        continue;
      }
      for (const property of Object.keys(properties)) {
        if (property === 'use' || !Object.hasOwn(base, property)) {
          problems.push(
            `${at} component "${component}.${property}": not a property of the base component`,
          );
        }
      }
    }
    if (problems.length > before) continue;
    const resolved = resolveTheme(tokens, name);
    for (const problem of [
      ...validateContrast(resolved),
      ...validateComponents(resolved),
    ]) {
      problems.push(`${at}: ${problem}`);
    }
  }
  return problems;
}

/** Every component property must name an existing base token (D-039). */
function validateComponents(tokens) {
  if (tokens.component === undefined) {
    return ['component: the section is required (D-039)'];
  }
  const problems = [];
  for (const [name, component] of entries(tokens.component)) {
    if (!IDENTIFIER.test(name)) {
      problems.push(`component "${name}": invalid name`);
    }
    if (typeof component.use !== 'string' || component.use.trim() === '') {
      problems.push(`component "${name}": "use" is required`);
    }
    for (const [property, reference] of componentProperties(component)) {
      if (!IDENTIFIER.test(property)) {
        problems.push(`component "${name}.${property}": invalid name`);
        continue;
      }
      const group = componentPropertyGroup(property);
      const known =
        typeof reference === 'string' &&
        !reference.startsWith('$') &&
        Object.hasOwn(tokens[group] ?? {}, reference);
      if (!known) {
        problems.push(
          `component "${name}.${property}": ${JSON.stringify(reference)} is not a ${group} token`,
        );
      }
    }
    const fg = tokens.color[component.foreground]?.value;
    const bg = tokens.color[component.background]?.value;
    if (fg && bg && HEX.test(fg) && HEX.test(bg)) {
      const ratio = contrastRatio(fg, bg);
      if (ratio < WCAG_AA_NORMAL_TEXT) {
        problems.push(
          `component "${name}": foreground on background is ${ratio.toFixed(2)}:1, below WCAG AA (${WCAG_AA_NORMAL_TEXT}:1)`,
        );
      }
    }
  }
  return problems;
}

function escapeRegExp(text) {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// ---------------------------------------------------------------------------
// Web (Tailwind CSS v4 theme and TypeScript brand constants)
// ---------------------------------------------------------------------------

export function renderCss(tokens) {
  const lines = [
    '/*',
    ` * ${GENERATED_NOTE}`,
    ' * Source: packages/design_tokens/tokens.json (docs/DESIGN_SYSTEM.md).',
    ' *',
    " * Tailwind's default colours, fonts, font sizes, radii, container sizes and",
    ' * breakpoints are reset so that only project tokens exist as utilities, e.g.',
    ' * `bg-brand-primary`, `text-text-secondary`, `text-heading1`, `rounded-medium`,',
    ' * `max-w-form`, `desktop:grid-cols-2`. Spacing keeps the 4 px multiplier.',
    ' *',
    ' * Component tokens (D-039) point at those values, e.g. `rounded-control`,',
    ' * `min-h-control`, `bg-button-primary-background`. The shared components use',
    ' * them, so one change in tokens.json restyles every screen.',
    ' */',
    '@theme {',
    '  --color-*: initial;',
  ];
  for (const [name, token] of entries(tokens.color)) {
    lines.push(`  --color-${kebabName(name)}: ${token.value.toLowerCase()};`);
  }
  lines.push('', '  /* Component colours (tokens.json "component"). */');
  for (const [name, component] of entries(tokens.component)) {
    for (const [property, reference] of componentProperties(component)) {
      if (componentPropertyGroup(property) !== 'color') continue;
      lines.push(
        `  --color-${kebabName(name)}-${kebabName(property)}: var(--color-${kebabName(reference)});`,
      );
    }
  }
  lines.push(
    '',
    '  --font-*: initial;',
    `  --font-sans: var(${tokens.font.webVariable}), ${tokens.font.fallback};`,
    '',
    '  /* Sizes only; apply the weight from the design-system table with font-* utilities. */',
    '  --text-*: initial;',
  );
  for (const [name, style] of entries(tokens.typography)) {
    lines.push(`  --text-${kebabName(name)}: ${rem(style.size)};`);
  }
  lines.push('', '  --radius-*: initial;');
  for (const [name, token] of entries(tokens.radius)) {
    lines.push(
      `  --radius-${kebabName(name)}: ${token.value >= 999 ? `${token.value}px` : rem(token.value)};`,
    );
  }
  lines.push('', '  /* Component radii, e.g. rounded-control. */');
  for (const [name, component] of entries(tokens.component)) {
    if (component.radius !== undefined) {
      lines.push(
        `  --radius-${kebabName(name)}: var(--radius-${kebabName(component.radius)});`,
      );
    }
  }
  lines.push('', '  /* Component minimum heights, e.g. min-h-control. */');
  for (const [name, component] of entries(tokens.component)) {
    if (component.minHeight !== undefined) {
      lines.push(
        `  --spacing-${kebabName(name)}: ${rem(tokens.layout[component.minHeight].value)};`,
      );
    }
  }
  lines.push('', '  --container-*: initial;');
  for (const [name, token] of entries(tokens.container)) {
    lines.push(`  --container-${kebabName(name)}: ${rem(token.value)};`);
  }
  lines.push('', '  --breakpoint-*: initial;');
  for (const [name, value] of entries(tokens.breakpoint)) {
    lines.push(`  --breakpoint-${kebabName(name)}: ${rem(value)};`);
  }
  lines.push('}', '');
  return lines.join('\n');
}

function tsString(value) {
  return `'${value.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
}

export function renderBrandTs(brand) {
  const lines = [
    `// ${GENERATED_NOTE}`,
    '// Source: packages/design_tokens/brand.json. Working names until the product',
    '// name and logo are decided.',
    '',
    'export const BRAND = {',
  ];
  for (const [key, value] of entries(brand)) {
    lines.push(`  ${key}: ${tsString(value)},`);
  }
  lines.push('} as const;', '');
  return lines.join('\n');
}

// ---------------------------------------------------------------------------
// Flutter (Dart token classes)
// ---------------------------------------------------------------------------

const DART_LINE = 80;

function dartString(value) {
  return `'${value.replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\$/g, '\\$')}'`;
}

/** A `static const` field, split after `=` like `dart format` when too long. */
function dartConst(type, name, expression) {
  const line = `  static const ${type} ${name} = ${expression};`;
  if (line.length <= DART_LINE) return [line];
  return [`  static const ${type} ${name} =`, `      ${expression};`];
}

/** A `static` getter, split after `=>` like `dart format` when too long. */
function dartGetter(type, name, expression) {
  const line = `  static ${type} get ${name} => ${expression};`;
  if (line.length <= DART_LINE) return [line];
  return [`  static ${type} get ${name} =>`, `      ${expression};`];
}

function dartNumber(value) {
  return String(value);
}

function dartColor(hex) {
  return `Color(0xFF${hex.slice(1).toUpperCase()})`;
}

/** `bottomNav` + `activeBackground` → `bottomNavActiveBackground`. */
function componentField(name, property) {
  return name + property[0].toUpperCase() + property.slice(1);
}

/** Every component property as `[component, property]`. */
function componentFields(tokens) {
  return entries(tokens.component).flatMap(([name, component]) =>
    componentProperties(component).map(([property]) => [name, property]),
  );
}

/** The resolved Dart literal of one component property in `tokens`. */
function componentValue(tokens, name, property) {
  const reference = tokens.component[name][property];
  const group = componentPropertyGroup(property);
  if (group === 'color') return dartColor(tokens.color[reference].value);
  return dartNumber(tokens[group][reference].value);
}

function dartDoc(text) {
  return `  /// ${text.endsWith('.') ? text : `${text}.`}`;
}

function dartHeader(extra = []) {
  return [
    `// ${GENERATED_NOTE}`,
    '// Source: packages/design_tokens/tokens.json (docs/DESIGN_SYSTEM.md).',
    ...extra,
  ];
}

export function renderDartPalette(tokens) {
  const themes = themeNames(tokens).map((name) => [
    name,
    resolveTheme(tokens, name),
  ]);
  const colors = entries(tokens.color);
  const components = componentFields(tokens);
  const lines = [
    ...dartHeader(),
    '',
    "import 'package:flutter/painting.dart';",
    '',
    '/// The colours, component values and font of one app identity (D-042,',
    '/// D-057). `AppColors`, `AppComponentTokens` and `AppTypography.fontFamily`',
    '/// read [current]. Each app picks its palette once with [use] in `main()`,',
    '/// before `runApp`; the identity never changes while the app runs.',
    'final class AppPalette {',
    '  const AppPalette._({',
    '    required this.name,',
    '    required this.fontFamily,',
    ...colors.map(([name]) => `    required this.${camelName(name)},`),
    ...components.map(
      ([name, property]) =>
        `    required this.${componentField(name, property)},`,
    ),
    '  });',
    '',
    '  /// The theme name in tokens.json.',
    '  final String name;',
    '',
    '  /// The font family, bundled in the `flutter_shared` package.',
    '  final String fontFamily;',
  ];
  for (const [name, token] of colors) {
    lines.push('', dartDoc(token.use), `  final Color ${camelName(name)};`);
  }
  for (const [name, property] of components) {
    const type =
      componentPropertyGroup(property) === 'color' ? 'Color' : 'double';
    lines.push(
      '',
      dartDoc(`Component token ${name}.${property}`),
      `  final ${type} ${componentField(name, property)};`,
    );
  }
  for (const [name, resolved] of themes) {
    const use =
      name === STANDARD_THEME
        ? 'The standard look: Admin Web and Shop App'
        : tokens.themes[name].use;
    lines.push(
      '',
      dartDoc(use),
      `  static const AppPalette ${name} = AppPalette._(`,
      `    name: ${dartString(name)},`,
      `    fontFamily: ${dartString(resolved.font.family)},`,
    );
    for (const [color, token] of entries(resolved.color)) {
      lines.push(`    ${camelName(color)}: ${dartColor(token.value)},`);
    }
    for (const [component, property] of components) {
      lines.push(
        `    ${componentField(component, property)}: ${componentValue(resolved, component, property)},`,
      );
    }
    lines.push('  );');
  }
  lines.push(
    '',
    '  /// Every palette in tokens.json.',
    `  static const List<AppPalette> values = [${themes.map(([name]) => name).join(', ')}];`,
    '',
    `  static AppPalette _current = ${STANDARD_THEME};`,
    '',
    `  /// The app's palette ([${STANDARD_THEME}] until [use] is called).`,
    '  static AppPalette get current => _current;',
    '',
    "  /// Picks the app's palette. Call once in `main()` before `runApp`.",
    '  static void use(AppPalette palette) {',
    '    _current = palette;',
    '  }',
    '}',
    '',
  );
  return lines.join('\n');
}

export function renderDartColors(tokens) {
  const lines = [
    ...dartHeader(),
    '',
    "import 'package:flutter/painting.dart';",
    '',
    "import 'app_palette.dart';",
    '',
    "/// Colour tokens of the app's palette (`AppPalette.current`). Paint shade",
    '/// colours are catalogue data and never belong here.',
    'abstract final class AppColors {',
  ];
  entries(tokens.color).forEach(([name, token], index) => {
    if (index > 0) lines.push('');
    lines.push(dartDoc(token.use));
    const field = camelName(name);
    lines.push(...dartGetter('Color', field, `AppPalette.current.${field}`));
  });
  lines.push('}', '');
  return lines.join('\n');
}

export function renderDartTypography(tokens) {
  const lines = [
    ...dartHeader(),
    '',
    "import 'package:flutter/painting.dart';",
    '',
    "import 'app_palette.dart';",
    '',
    '/// Typography tokens. The font family is applied by `AppTheme`, so the',
    '/// styles deliberately leave `fontFamily` unset.',
    'abstract final class AppTypography {',
    "  /// The app palette's family, bundled in the `flutter_shared` package (see",
    '  /// its `pubspec.yaml`).',
    ...dartGetter('String', 'fontFamily', 'AppPalette.current.fontFamily'),
    ...dartConst(
      'String',
      'fontPackage',
      dartString(tokens.font.flutterPackage),
    ),
  ];
  for (const [name, style] of entries(tokens.typography)) {
    lines.push(
      '',
      dartDoc(style.use),
      `  static const TextStyle ${name} = TextStyle(`,
      `    fontSize: ${dartNumber(style.size)},`,
      `    fontWeight: FontWeight.w${style.weight},`,
      '  );',
    );
  }
  lines.push('}', '');
  return lines.join('\n');
}

export function renderDartRadius(tokens) {
  const lines = [
    ...dartHeader(),
    '',
    '/// Corner-radius tokens.',
    'abstract final class AppRadius {',
  ];
  entries(tokens.radius).forEach(([name, token], index) => {
    if (index > 0) lines.push('');
    lines.push(
      dartDoc(token.use),
      ...dartConst('double', name, dartNumber(token.value)),
    );
  });
  lines.push('}', '');
  return lines.join('\n');
}

export function renderDartSpacing(tokens) {
  const lines = [
    ...dartHeader(),
    '',
    `/// ${tokens.spacing.base} px-based spacing scale. Use these values instead of`,
    '/// one-off spacing literals.',
    'abstract final class AppSpacing {',
  ];
  for (const step of tokens.spacing.scale) {
    lines.push(...dartConst('double', `s${step}`, dartNumber(step)));
  }
  for (const [name, token] of entries(tokens.layout)) {
    lines.push(
      '',
      dartDoc(token.use),
      ...dartConst('double', name, dartNumber(token.value)),
    );
  }
  lines.push('}', '');
  return lines.join('\n');
}

export function renderDartLayout(tokens) {
  const lines = [
    ...dartHeader(),
    '',
    '/// Content widths and breakpoints (logical pixels), shared with the web.',
    'abstract final class AppLayout {',
  ];
  const fields = [
    ...entries(tokens.container).map(([name, token]) => [
      `${name}MaxWidth`,
      token.value,
      token.use,
    ]),
    ...entries(tokens.breakpoint).map(([name, value]) => [
      `${name}Breakpoint`,
      value,
      `Width at which the ${name} layout starts`,
    ]),
  ];
  fields.forEach(([name, value, use], index) => {
    if (index > 0) lines.push('');
    lines.push(dartDoc(use), ...dartConst('double', name, dartNumber(value)));
  });
  lines.push('}', '');
  return lines.join('\n');
}

export function renderDartComponents(tokens) {
  const lines = [
    ...dartHeader(),
    '',
    "import 'package:flutter/painting.dart';",
    '',
    "import 'app_palette.dart';",
    '',
    "/// What each shared component uses (D-039), from the app's palette",
    '/// (`AppPalette.current`). The components read these, so one change in',
    '/// tokens.json restyles every screen.',
    'abstract final class AppComponentTokens {',
  ];
  entries(tokens.component).forEach(([name, component], index) => {
    if (index > 0) lines.push('');
    lines.push(dartDoc(component.use));
    for (const [property] of componentProperties(component)) {
      const group = componentPropertyGroup(property);
      const type = group === 'color' ? 'Color' : 'double';
      const field = componentField(name, property);
      lines.push(...dartGetter(type, field, `AppPalette.current.${field}`));
    }
  });
  lines.push('}', '');
  return lines.join('\n');
}

export function renderDartBrand(brand) {
  const lines = [
    `// ${GENERATED_NOTE}`,
    '// Source: packages/design_tokens/brand.json. Working names until the product',
    '// name and logo are decided.',
    '',
    '/// Product and app names shown in the apps.',
    'abstract final class AppBrand {',
  ];
  entries(brand).forEach(([key, value], index) => {
    if (index > 0) lines.push('');
    lines.push(...dartConst('String', key, dartString(value)));
  });
  lines.push('}', '');
  return lines.join('\n');
}

/** Every generated file as `{ path, content }`, paths relative to the root. */
export function renderAll(tokens, brand) {
  return [
    { path: OUTPUT_PATHS.css, content: renderCss(tokens) },
    { path: OUTPUT_PATHS.brandTs, content: renderBrandTs(brand) },
    { path: OUTPUT_PATHS.dartColors, content: renderDartColors(tokens) },
    {
      path: OUTPUT_PATHS.dartTypography,
      content: renderDartTypography(tokens),
    },
    { path: OUTPUT_PATHS.dartRadius, content: renderDartRadius(tokens) },
    { path: OUTPUT_PATHS.dartSpacing, content: renderDartSpacing(tokens) },
    { path: OUTPUT_PATHS.dartLayout, content: renderDartLayout(tokens) },
    {
      path: OUTPUT_PATHS.dartComponents,
      content: renderDartComponents(tokens),
    },
    { path: OUTPUT_PATHS.dartPalette, content: renderDartPalette(tokens) },
    { path: OUTPUT_PATHS.dartBrand, content: renderDartBrand(brand) },
  ];
}
